SELECT DISTINCT e.EXPERT_USER_ID userId, e.EXPERT_USERNAME userName, e.EXPERT_FULL_NAME fullName, e.EXPERT_LEVEL expertLevel FROM scc_npm_sou_expert e JOIN scc_npm_sou_expert_apply a ON a.EXPERT_APPLY_ID = e.EXPERT_APPLY_ID JOIN scc_npm_sou_expert_org o ON o.EXPERT_APPLY_ID = e.EXPERT_APPLY_ID and o.ORG_ID IN
#{item}
JOIN scc_npm_sou_expert_category c ON c.EXPERT_APPLY_ID = e.EXPERT_APPLY_ID AND c.CATEGORY_CODE= #{categoryCode}
and e.HAS_QUITE='N' AND e.HAS_FROZEN='N'
and a.APPLY_BY_ID not in
#{item}

SELECT * FROM ( SELECT DISTINCT g.USER_ID FROM meicloud_usrm_cloud_biz_supplier_cooperate.scc_npm_pr_require_group g JOIN meicloud_usrm_cloud_biz_supplier_cooperate.scc_pr_requirement_head h ON h.REQUIREMENT_HEAD_ID = g.REQUIREMENT_HEAD_ID WHERE g.GROUP_TYPE='TECH' AND h.REQUIREMENT_HEAD_NUM IN
#{item}
) pr

SELECT e.EXPERT_USER_ID userId, e.EXPERT_USERNAME userName, e.EXPERT_FULL_NAME fullName, w.WORK_UNIT vendorName, r.RELATIVE_NAME relationsFullName, r.WORK_UNIT relationVendorName FROM scc_npm_sou_expert e JOIN scc_npm_sou_expert_apply a ON a.EXPERT_APPLY_ID = e.EXPERT_APPLY_ID LEFT JOIN scc_npm_sou_expert_work w ON w.EXPERT_APPLY_ID = a.EXPERT_APPLY_ID LEFT JOIN scc_npm_sou_expert_work_relate r ON r.EXPERT_APPLY_ID = a.EXPERT_APPLY_ID WHERE e.EXPERT_USER_ID IN
#{item}
AND e.HAS_QUITE='N' AND e.HAS_FROZEN='N'
